css:
.retire-sim-container {
    padding: 28px;
    background: #06080f;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e0e6f0;
}

.retire-sim-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    border-left: 4px solid #00ff88;
    padding: 22px 28px;
    margin-bottom: 28px;
    background: linear-gradient(90deg, rgba(0,255,136,0.08), rgba(0,255,136,0.0));
    border-radius: 0 8px 8px 0;
    flex-wrap: wrap;
    gap: 16px;
}

.retire-sim-header-left h1 {
    color: #00ff88;
    font-size: 1.6rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin: 0 0 6px 0;
    font-weight: 700;
}

.retire-sim-subtitle {
    color: #9aa5b1;
    font-size: 0.9rem;
    max-width: 620px;
    margin: 0;
    line-height: 1.5;
}

.retire-sim-period-counter {
    background: #0d1421;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
    padding: 12px 18px;
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.95rem;
    color: #e0e6f0;
}

.retire-sim-counter-label {
    color: #6b7280;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.12em;
    margin-right: 4px;
}

.retire-sim-decade-tag {
    background: #00ff88;
    color: #06080f;
    padding: 3px 10px;
    border-radius: 4px;
    font-weight: 700;
    font-size: 0.85rem;
    margin-left: 8px;
    letter-spacing: 0.05em;
}

.retire-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
}

.retire-sim-kpi-card {
    background: #0d1421;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 18px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease, transform 0.2s ease;
}

.retire-sim-kpi-card:hover {
    transform: translateY(-2px);
    border-color: #2d3f55;
}

.retire-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00ff88, #00bfff);
}

.retire-sim-kpi-age::before { background: linear-gradient(90deg, #ffd166, #ff6b35); }
.retire-sim-kpi-balance::before { background: linear-gradient(90deg, #00ff88, #00bfff); }
.retire-sim-kpi-match::before { background: linear-gradient(90deg, #a78bfa, #00ff88); }

.retire-sim-kpi-label {
    color: #6b7280;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
    font-weight: 600;
}

.retire-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #00ff88;
    letter-spacing: -0.02em;
}

.retire-sim-kpi-age .retire-sim-kpi-value { color: #ffd166; }
.retire-sim-kpi-match .retire-sim-kpi-value { color: #a78bfa; }

.retire-sim-section-tag {
    color: #6b7280;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    font-weight: 600;
    margin: 0 0 14px 0;
    display: block;
}

.retire-sim-briefing {
    background: #0d1421;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #00bfff;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 28px;
}

.retire-sim-briefing-text {
    color: #c5cdd9;
    font-size: 0.98rem;
    line-height: 1.6;
}

.retire-sim-controls {
    background: #0d1421;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 26px;
    margin-bottom: 28px;
}

.retire-sim-control-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 22px;
    margin-bottom: 22px;
}

.retire-sim-control-block label {
    display: block;
    color: #9aa5b1;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 600;
}

.retire-sim-controls input[type="number"],
.retire-sim-controls select {
    background: #06080f;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.retire-sim-controls input[type="number"]:focus,
.retire-sim-controls select:focus {
    outline: none;
    border-color: #00ff88;
    box-shadow: 0 0 0 2px rgba(0,255,136,0.15);
}

.retire-sim-controls select option {
    background: #0d1421;
    color: #e0e6f0;
}

.retire-sim-help {
    display: block;
    margin-top: 8px;
    color: #6b7280;
    font-size: 0.78rem;
    line-height: 1.4;
}

.retire-sim-button-row {
    display: flex;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
}

.retire-sim-submit-btn {
    background: #00ff88;
    color: #06080f;
    border: none;
    border-radius: 4px;
    padding: 12px 28px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.85rem;
    transition: transform 0.15s ease, box-shadow 0.2s ease;
}

.retire-sim-submit-btn:hover {
    background: #00ff88;
    color: #06080f;
    transform: translateY(-1px);
    box-shadow: 0 6px 18px rgba(0,255,136,0.25);
}

.retire-sim-undo-btn {
    background: transparent;
    color: #9aa5b1;
    border: 1px solid #2d3f55;
    border-radius: 4px;
    padding: 10px 18px;
    font-size: 0.85rem;
}

.retire-sim-undo-btn:hover {
    background: #1f2d3d;
    color: #e0e6f0;
    border-color: #2d3f55;
}

.retire-sim-chart-wrapper {
    background: #0d1421;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 28px;
}

.retire-sim-chart {
    height: 380px;
    position: relative;
}

.retire-sim-history {
    background: #0d1421;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 28px;
}

.retire-sim-history table {
    width: 100%;
    color: #e0e6f0;
    background: transparent;
    margin: 0;
}

.retire-sim-history table thead th {
    background: #06080f;
    color: #6b7280;
    border: none;
    border-bottom: 1px solid #1f2d3d;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.12em;
    padding: 12px;
    font-weight: 600;
}

.retire-sim-history table tbody td {
    background: transparent;
    color: #e0e6f0;
    border: none;
    border-bottom: 1px solid #1a2332;
    padding: 12px;
    font-size: 0.92rem;
}

.retire-sim-history table tbody tr:hover td {
    background: rgba(0,255,136,0.04);
}

@media (max-width: 768px) {
    .retire-sim-container { padding: 16px; }
    .retire-sim-header { flex-direction: column; padding: 18px; }
    .retire-sim-header-left h1 { font-size: 1.25rem; }
    .retire-sim-subtitle { font-size: 0.85rem; }
    .retire-sim-kpi-value { font-size: 1.4rem; }
    .retire-sim-controls { padding: 18px; }
    .retire-sim-chart { height: 300px; }
}

