(function() {
    'use strict';

    class RetirementGameAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'The Retirement Game';
            this.version = '1.1.0';

            this.DECADES = [
                {
                    label: '22-32',
                    age_start: 22,
                    age_end: 32,
                    description: 'Foundation. You are 22, fresh out of school, $40k salary, single, renting. The HR rep just dropped a 401(k) packet on your desk. Decade 1 will define your retirement more than every other decade combined. Capture the match. Pick the cheap fund. Start now.'
                },
                {
                    label: '32-42',
                    age_start: 32,
                    age_end: 42,
                    description: 'Family and Income Growth. Your salary climbs from ~$58k toward ~$79k. Maybe marriage. Maybe a first child. The big test of the decade: do your raises feed your 401(k), or your lifestyle? Lifestyle creep is silent and expensive.'
                },
                {
                    label: '42-52',
                    age_start: 42,
                    age_end: 52,
                    description: 'Peak Earning. Salary climbs to ~$107k. The unplanned event of the decade: a layoff. Your 401(k) balance is real money now. Will you rollover that 401(k) to an IRA, or cash it out for a quick check at 40 cents on the dollar?'
                },
                {
                    label: '52-62',
                    age_start: 52,
                    age_end: 62,
                    description: 'Pre-Retirement. Salary peaks near $130k. The market may crash at 55 — every market crash since 1928 has been followed by a recovery, but the investors who sold to cash crystallized the loss. The behavioral test: do you panic sell, or hold the line?'
                },
                {
                    label: '62-65',
                    age_start: 62,
                    age_end: 65,
                    description: 'Settle-Up. The moment of truth. Choose when to claim Social Security: 62 (reduced ~30%), 67 (full retirement age), or 70 (delayed credits +24%). The right answer depends on health and longevity, but the default 62 is usually wrong.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    age: 22,
                    salary: 40000,
                    bal_traditional: 0,
                    bal_roth: 0,
                    bal_taxable: 0,
                    match_captured: 0,
                    match_forfeited: 0,
                    peer_late_balance: 0,
                    peer_skipped_balance: 0,
                    peer_active_balance: 0,
                    balance_history: [0],
                    peer_late_history: [0],
                    peer_skipped_history: [0],
                    peer_active_history: [0],
                    contribution_history: [],
                    notes_log: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    contribution_rate: 6,
                    roth_split: 50,
                    fund_er: 0.04,
                    decade_choice: 'stay'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var rateInput = document.getElementById('contributionRateInput');
            var rothInput = document.getElementById('rothSplitInput');
            var fundInput = document.getElementById('fundSelect');
            var choiceInput = document.getElementById('decadeChoiceSelect');

            if (rateInput) decisions.contribution_rate = parseFloat(rateInput.value);
            if (rothInput) decisions.roth_split = parseFloat(rothInput.value);
            if (fundInput) decisions.fund_er = parseFloat(fundInput.value);
            if (choiceInput) decisions.decade_choice = choiceInput.value;

            if (isNaN(decisions.contribution_rate) || decisions.contribution_rate < 0 || decisions.contribution_rate > 25) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('rate_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.roth_split) || decisions.roth_split < 0 || decisions.roth_split > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('roth_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const period = state.currentPeriod;
            const decade = this.DECADES[period - 1];
            const years = decade.age_end - decade.age_start;

            const REAL_RETURN = 0.07;
            const RAISE_RATE = 0.03;
            const MATCH_CAP = 0.06;
            const MATCH_RATE = 0.5;

            const fundDrag = (d.fund_er || 0) / 100;
            const netReturn = REAL_RETURN - fundDrag;

            let rate = (d.contribution_rate || 0) / 100;
            const rothPct = (d.roth_split || 0) / 100;

            let salary = ds.salary;
            let balTrad = ds.bal_traditional;
            let balRoth = ds.bal_roth;
            let balTaxable = ds.bal_taxable;
            let totalContribThisDecade = 0;
            let totalMatchThisDecade = 0;
            let matchForfeited = 0;
            let cashoutPenalty = 0;
            let crashLoss = 0;
            let ssMonthly = 0;
            let eventNote = '';

            for (let y = 0; y < years; y++) {
                if (period === 1 && d.decade_choice === 'switch_jobs' && y === 2) {
                    const forfeit = totalMatchThisDecade;
                    balTrad -= forfeit;
                    matchForfeited += forfeit;
                    salary = 46000;
                    eventNote = 'Switched jobs at year 2 — forfeited unvested match';
                }

                const matchableRate = Math.min(rate, MATCH_CAP);
                const matchThisYear = matchableRate * salary * MATCH_RATE;
                const contribThisYear = rate * salary;

                const tradContrib = contribThisYear * (1 - rothPct);
                const rothContrib = contribThisYear * rothPct;

                balTrad += tradContrib + matchThisYear;
                balRoth += rothContrib;

                totalContribThisDecade += contribThisYear;
                totalMatchThisDecade += matchThisYear;

                balTrad *= (1 + netReturn);
                balRoth *= (1 + netReturn);
                balTaxable *= (1 + netReturn);

                if (period === 2 && d.decade_choice === 'absorb_raises') {
                    salary *= (1 + RAISE_RATE);
                    rate *= 0.97;
                } else {
                    salary *= (1 + RAISE_RATE);
                }
            }

            if (period === 3 && d.decade_choice === 'cashout') {
                const pre = balTrad;
                cashoutPenalty = pre * 0.40;
                balTrad = pre * 0.60;
                eventNote = 'Cashed out 401(k) on layoff — paid taxes plus 10% penalty';
            } else if (period === 3 && d.decade_choice === 'rollover') {
                eventNote = 'Rolled over 401(k) to IRA — no tax, no penalty, full compounding preserved';
            }

            if (period === 4 && d.decade_choice === 'panic_sell') {
                const pre = balTrad + balRoth;
                crashLoss = pre * 0.35;
                balTrad *= 0.65;
                balRoth *= 0.65;
                eventNote = 'Sold to cash during the crash — crystallized the loss, missed the recovery';
            } else if (period === 4 && d.decade_choice === 'rebalance') {
                eventNote = 'Held through the crash and rebalanced — captured the recovery';
            }

            if (period === 5) {
                if (d.decade_choice === 'ss_62') {
                    ssMonthly = 1820;
                    eventNote = 'Claimed Social Security at 62 — reduced about 30% for life';
                } else if (d.decade_choice === 'ss_67') {
                    ssMonthly = 2600;
                    eventNote = 'Claimed Social Security at full retirement age 67';
                } else if (d.decade_choice === 'ss_70') {
                    ssMonthly = 3220;
                    eventNote = 'Delayed Social Security to 70 — +24% benefit for life';
                } else {
                    ssMonthly = 2600;
                }
            }

            this._advancePeer(ds, 'late', period, years, REAL_RETURN);
            this._advancePeer(ds, 'skipped', period, years, REAL_RETURN);
            this._advancePeer(ds, 'active', period, years, REAL_RETURN);

            ds.salary = salary;
            ds.bal_traditional = balTrad;
            ds.bal_roth = balRoth;
            ds.bal_taxable = balTaxable;
            ds.match_captured += totalMatchThisDecade;
            ds.match_forfeited += matchForfeited;
            ds.age = decade.age_end;

            const totalBalance = balTrad + balRoth + balTaxable;
            ds.balance_history.push(totalBalance);
            ds.contribution_history.push(totalContribThisDecade);
            if (eventNote) ds.notes_log.push('Decade ' + period + ': ' + eventNote);

            // Advance the briefing + the decade-specific choice menu to the NEXT decade once the
            // framework increments currentPeriod (next tick). Without this the menu lagged one decade
            // behind, making the decade-2..5 events (raises, layoff, crash, Social Security) unreachable.
            var _self = this;
            setTimeout(function() { _self._updateBriefing(window.mySimulation.state); }, 0);

            return {
                period: period,
                decade_label: decade.label,
                age_end: decade.age_end,
                salary: Math.round(salary),
                contributions: Math.round(totalContribThisDecade),
                match_captured: Math.round(totalMatchThisDecade),
                match_forfeited: Math.round(matchForfeited),
                cashout_penalty: Math.round(cashoutPenalty),
                crash_loss: Math.round(crashLoss),
                ss_monthly: ssMonthly,
                total_balance: Math.round(totalBalance),
                bal_traditional: Math.round(balTrad),
                bal_roth: Math.round(balRoth),
                peer_late: Math.round(ds.peer_late_balance),
                peer_skipped: Math.round(ds.peer_skipped_balance),
                peer_active: Math.round(ds.peer_active_balance),
                event_note: eventNote
            };
        }

        _advancePeer(ds, type, period, years, baseReturn) {
            const RAISE = 0.03;
            const MATCH_CAP = 0.06;
            const MATCH_RATE = 0.5;
            const RATE = 0.06;

            let salary = 40000;
            for (let p = 1; p < period; p++) {
                salary *= Math.pow(1 + RAISE, this.DECADES[p - 1].age_end - this.DECADES[p - 1].age_start);
            }

            let bal;
            let netReturn = baseReturn;
            let peerRate = RATE;
            let active = true;

            if (type === 'late') {
                bal = ds.peer_late_balance;
                if (period === 1) active = false;
            } else if (type === 'skipped') {
                bal = ds.peer_skipped_balance;
                if (period === 1) peerRate = 0.0;
            } else if (type === 'active') {
                bal = ds.peer_active_balance;
                netReturn = baseReturn - 0.0106;
            }

            for (let y = 0; y < years; y++) {
                if (active) {
                    const contribution = salary * peerRate;
                    const match = Math.min(peerRate, MATCH_CAP) * salary * MATCH_RATE;
                    bal += contribution + match;
                }
                bal *= (1 + netReturn);
                salary *= (1 + RAISE);
            }

            if (type === 'late') {
                ds.peer_late_balance = bal;
                ds.peer_late_history.push(bal);
            } else if (type === 'skipped') {
                ds.peer_skipped_balance = bal;
                ds.peer_skipped_history.push(bal);
            } else if (type === 'active') {
                ds.peer_active_balance = bal;
                ds.peer_active_history.push(bal);
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('ageDisplay', 'domainState.age',
                (v) => Math.round(v));
            uiManager.bind('salaryDisplay', 'domainState.salary',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('balanceDisplay', 'domainState.bal_traditional',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('rothDisplay', 'domainState.bal_roth',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('matchDisplay', 'domainState.match_captured',
                (v) => '$' + Math.round(v).toLocaleString());
        }

        getChartConfig() {
            return {
                compoundChart: {
                    type: 'line',
                    data: {
                        labels: ['Age 22'],
                        datasets: [
                            {
                                label: 'You',
                                data: [],
                                borderColor: '#00ff88',
                                backgroundColor: 'rgba(0,255,136,0.12)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: '#00ff88'
                            },
                            {
                                label: 'Started at 32 (peer)',
                                data: [],
                                borderColor: '#ff6b35',
                                borderDash: [6, 4],
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                pointRadius: 3
                            },
                            {
                                label: 'Skipped match in decade 1 (peer)',
                                data: [],
                                borderColor: '#ffd166',
                                borderDash: [3, 3],
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                pointRadius: 3
                            },
                            {
                                label: 'Active fund 1.10% ER (peer)',
                                data: [],
                                borderColor: '#a78bfa',
                                borderDash: [8, 2],
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                pointRadius: 3
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: {
                                display: true,
                                text: 'Compound Growth — Your Balance vs. Peers',
                                color: '#e0e6f0',
                                font: { size: 14, weight: '600' }
                            },
                            legend: {
                                labels: { color: '#c5cdd9', font: { size: 11 } }
                            },
                            tooltip: {
                                backgroundColor: '#0d1421',
                                borderColor: '#2d3f55',
                                borderWidth: 1,
                                titleColor: '#00ff88',
                                bodyColor: '#e0e6f0',
                                callbacks: {
                                    label: function(ctx) {
                                        return ctx.dataset.label + ': $' + Math.round(ctx.parsed.y).toLocaleString();
                                    }
                                }
                            }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                ticks: {
                                    color: '#9aa5b1',
                                    callback: function(v) { return '$' + (v / 1000).toFixed(0) + 'k'; }
                                },
                                grid: { color: 'rgba(31,45,61,0.6)' }
                            },
                            x: {
                                ticks: { color: '#9aa5b1' },
                                grid: { color: 'rgba(31,45,61,0.4)' }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const fullLabels = ['Age 22', 'Age 32', 'Age 42', 'Age 52', 'Age 62', 'Age 65'];
            const labels = fullLabels.slice(0, ds.balance_history.length);
            return {
                compoundChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.balance_history.slice() },
                        { data: ds.peer_late_history.slice() },
                        { data: ds.peer_skipped_history.slice() },
                        { data: ds.peer_active_history.slice() }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const last = history[history.length - 1];
            const finalBalance = (last.results && last.results.total_balance) || 0;
            const peerLate = (last.results && last.results.peer_late) || 0;
            const peerSkipped = (last.results && last.results.peer_skipped) || 0;
            const peerActive = (last.results && last.results.peer_active) || 0;
            const ssMonthly = (last.results && last.results.ss_monthly) || 0;
            const totalMatch = history.reduce((s, h) => s + ((h.results && h.results.match_captured) || 0), 0);

            const _t = function(k, vars){ return window.mySimulation.t(k, vars); };
            const insights = [];
            const deltaLate = finalBalance - peerLate;
            const deltaActive = finalBalance - peerActive;

            if (deltaLate > 0) {
                insights.push(_t('insight_ahead_late', { amount: '$' + deltaLate.toLocaleString() }));
            } else {
                insights.push(_t('insight_behind_late'));
            }
            if (deltaActive > 0) {
                insights.push(_t('insight_ahead_active', { amount: '$' + deltaActive.toLocaleString() }));
            }
            insights.push(_t('insight_match_total', { amount: '$' + Math.round(totalMatch).toLocaleString() }));
            insights.push(_t('insight_decade1'));
            if (ssMonthly > 0) {
                insights.push(_t('insight_ss', { amount: '$' + ssMonthly.toLocaleString() }));
            }

            const annualWithdrawal = Math.round(finalBalance * 0.04);

            let performance = _t('perf_beginner'), tier = 'beginner';
            if (finalBalance > 600000) { performance = _t('perf_ontrack'); tier = 'ontrack'; }
            if (finalBalance > 1000000) { performance = _t('perf_good'); tier = 'good'; }
            if (finalBalance > 1300000) { performance = _t('perf_excellent'); tier = 'excellent'; }

            return {
                totalProfit: finalBalance,
                avgProfit: annualWithdrawal,
                performance: performance,
                tier: tier,
                insights: insights
            };
        }

        getHint(state, results) {
            if (state.currentPeriod <= 2 && state.decisions.contribution_rate < 6) {
                return window.mySimulation.t('hint_skip_match');
            }
            if (state.decisions.fund_er > 1) {
                return window.mySimulation.t('hint_high_er');
            }
            if (state.currentPeriod === 2 && state.decisions.contribution_rate <= 6) {
                return window.mySimulation.t('hint_lifestyle_creep');
            }
            if (results && results.cashout_penalty > 0) {
                return window.mySimulation.t('hint_cashout');
            }
            if (results && results.crash_loss > 0) {
                return window.mySimulation.t('hint_panic');
            }
            if (state.currentPeriod === 1 && state.decisions.roth_split < 50) {
                return window.mySimulation.t('hint_roth_low');
            }
            return null;
        }

