            const idx = Math.min((state.currentPeriod || 1) - 1, this.DECADES.length - 1);
            const decade = this.DECADES[idx];

            const _t = (window.mySimulation && window.mySimulation.t) ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            const briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = _t('decade' + (idx + 1) + '_desc');

            const decadeLabelEl = document.getElementById('decadeLabel');
            if (decadeLabelEl) decadeLabelEl.textContent = decade.label;

            const choiceSelect = document.getElementById('decadeChoiceSelect');
            const choiceLabel = document.getElementById('decadeChoiceLabel');
            if (!choiceSelect || !choiceLabel) return;

            choiceSelect.innerHTML = '';
            let labelText = '';
            let options = [];

            if (idx === 0) {
                labelText = _t('ch1_label');
                options = [
                    { v: 'stay', t: _t('ch1_stay') },
                    { v: 'switch_jobs', t: _t('ch1_switch') }
                ];
            } else if (idx === 1) {
                labelText = _t('ch2_label');
                options = [
                    { v: 'standard', t: _t('ch2_standard') },
                    { v: 'absorb_raises', t: _t('ch2_absorb') }
                ];
            } else if (idx === 2) {
                labelText = _t('ch3_label');
                options = [
                    { v: 'rollover', t: _t('ch3_rollover') },
                    { v: 'cashout', t: _t('ch3_cashout') },
                    { v: 'leave', t: _t('ch3_leave') }
                ];
            } else if (idx === 3) {
                labelText = _t('ch4_label');
                options = [
                    { v: 'standard', t: _t('ch4_standard') },
                    { v: 'panic_sell', t: _t('ch4_panic') },
                    { v: 'rebalance', t: _t('ch4_rebalance') }
                ];
            } else if (idx === 4) {
                labelText = _t('ch5_label');
                options = [
                    { v: 'ss_62', t: _t('ch5_62') },
                    { v: 'ss_67', t: _t('ch5_67') },
                    { v: 'ss_70', t: _t('ch5_70') }
                ];
            }

            choiceLabel.textContent = labelText;
            options.forEach(function(o) {
                const opt = document.createElement('option');
                opt.value = o.v;
                opt.textContent = o.t;
                choiceSelect.appendChild(opt);
            });
        }

